#### Phase 1: S3 Bucket Provisioning (All Variations)

1. Provision the S3 bucket with a name that does not contain PHI.
2. Enable Block Public Access (all four settings).
3. Enable SSE-KMS encryption.
4. Enable versioning.
5. Enable S3 access logging directed to the organization's log bucket.
6. Do **not** enable the S3 static website hosting endpoint.

```terraform
resource "aws_s3_bucket" "assets" {
  bucket = var.bucket_name  # Must not contain PHI
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.kms_key_arn
    }
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_logging" "assets" {
  bucket        = aws_s3_bucket.assets.id
  target_bucket = var.log_bucket_id
  target_prefix = "${var.app_name}/s3-access/"
}
```

